'use client';

import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';
import { fontWeights } from '@/lib/font-weight';
import { useShape } from '@/lib/shape-context';
import { typeClass } from '@/lib/size-context';

// ---------------------------------------------------------------------------
// The frame both auth screens share. The form sits in the first column.
// Once the page itself is wide enough (@xl on this element, not the
// viewport), a muted panel takes the trailing two fifths: a mark and one
// line. Below that width the form is the whole screen.
// ---------------------------------------------------------------------------

/** One @, and a dot in the domain. Shared so Login and Register disagree
 *  about an address in the same way. */
export function emailError(value: string): string | null {
  const email = value.trim();
  if (!email) return 'Enter an email address.';
  const at = email.indexOf('@');
  if (at <= 0 || !email.slice(at + 1).includes('.')) return 'Enter a valid email address.';
  return null;
}

export function AuthLink({ href, children }: { href: string; children: ReactNode }) {
  return (
    <a
      href={href}
      className="text-foreground underline-offset-4 transition-colors duration-80 hover:underline"
      style={{ fontVariationSettings: fontWeights.semibold }}
    >
      {children}
    </a>
  );
}

export function AuthPanel({
  title,
  description,
  brand = 'Acme',
  aside,
  children,
  footer,
  className,
}: {
  title: string;
  description: string;
  /** The word whose first letter becomes the mark. Replace the mark in this
   *  file to use your own logo. */
  brand?: string;
  aside: string;
  children: ReactNode;
  footer?: ReactNode;
  className?: string;
}) {
  const shape = useShape();
  const initial = brand.trim().slice(0, 1).toUpperCase();

  return (
    <div className={cn('@container flex h-full min-h-svh w-full bg-background', className)}>
      <div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-y-auto">
        <div className="m-auto flex w-full max-w-sm flex-col gap-8 px-6 py-12">
          <div className="flex flex-col gap-2">
            <h1
              className={cn(typeClass('display'), 'text-foreground')}
              style={{ fontVariationSettings: fontWeights.semibold }}
            >
              {title}
            </h1>
            <p className={cn(typeClass('body'), 'text-muted-foreground')}>{description}</p>
          </div>
          {children}
          {footer ? (
            <p className={cn(typeClass('body'), 'text-muted-foreground')}>{footer}</p>
          ) : null}
        </div>
      </div>
      <aside className="hidden w-2/5 shrink-0 flex-col justify-between border-l border-border bg-muted p-8 @xl:flex">
        <div
          aria-hidden
          className={cn(
            'flex size-10 items-center justify-center bg-foreground text-background select-none',
            shape.button,
            typeClass('subtitle'),
          )}
          style={{ fontVariationSettings: fontWeights.semibold }}
        >
          {initial}
        </div>
        <p
          className={cn(typeClass('title'), 'max-w-xs text-foreground')}
          style={{ fontVariationSettings: fontWeights.semibold }}
        >
          {aside}
        </p>
      </aside>
    </div>
  );
}

'use client';

import { useId, useState, type FormEvent } from 'react';
import { Button } from '@/components/ui/button';
import { Field, FieldError, FieldGroup, FieldLabel } from '@/components/ui/field';
import { Input } from '@/components/ui/input';
import { AuthLink, AuthPanel, emailError } from '@/components/auth/auth-panel';

// ---------------------------------------------------------------------------
// Account screen. Same frame as Login. Name, email, and password stay quiet
// until submit. loginHref (default /login) is the way back.
// ---------------------------------------------------------------------------

export interface RegisterValues {
  name: string;
  email: string;
  password: string;
}

export function RegisterPage({
  brand,
  loginHref = '/login',
  aside = 'The workspace starts with this account.',
  pending = false,
  className,
  onSubmit,
}: {
  /** Wordmark on the quiet panel. The first letter becomes the mark. */
  brand?: string;
  /** Where "Sign in" goes. */
  loginHref?: string;
  /** The line at the bottom of the quiet panel. */
  aside?: string;
  /** Disables the fields and shows the button spinner. */
  pending?: boolean;
  className?: string;
  /** Called with the trimmed name and email once every field passes. */
  onSubmit?: (values: RegisterValues) => void;
}) {
  const id = useId();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [nameMessage, setNameMessage] = useState<string | null>(null);
  const [emailMessage, setEmailMessage] = useState<string | null>(null);
  const [passwordMessage, setPasswordMessage] = useState<string | null>(null);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (pending) return;
    const nextName = name.trim() ? null : 'Enter your name.';
    const nextEmail = emailError(email);
    const nextPassword = password ? null : 'Enter a password.';
    setNameMessage(nextName);
    setEmailMessage(nextEmail);
    setPasswordMessage(nextPassword);
    if (nextName || nextEmail || nextPassword) return;
    onSubmit?.({ name: name.trim(), email: email.trim(), password });
  }

  return (
    <AuthPanel
      title="Create an account"
      description="Start with your name and an email."
      brand={brand}
      aside={aside}
      className={className}
      footer={
        <>
          Already have an account? <AuthLink href={loginHref}>Sign in</AuthLink>
        </>
      }
    >
      <form noValidate onSubmit={handleSubmit} className="flex flex-col gap-6">
        <FieldGroup>
          <Field data-invalid={nameMessage ? true : undefined}>
            <FieldLabel htmlFor={`${id}-name`}>Name</FieldLabel>
            <Input
              id={`${id}-name`}
              name="name"
              type="text"
              autoComplete="name"
              value={name}
              disabled={pending}
              aria-invalid={nameMessage ? true : undefined}
              onChange={(event) => {
                setName(event.target.value);
                setNameMessage(null);
              }}
            />
            <FieldError>{nameMessage}</FieldError>
          </Field>
          <Field data-invalid={emailMessage ? true : undefined}>
            <FieldLabel htmlFor={`${id}-email`}>Email</FieldLabel>
            <Input
              id={`${id}-email`}
              name="email"
              type="email"
              autoComplete="email"
              autoCapitalize="none"
              spellCheck={false}
              value={email}
              disabled={pending}
              aria-invalid={emailMessage ? true : undefined}
              onChange={(event) => {
                setEmail(event.target.value);
                setEmailMessage(null);
              }}
            />
            <FieldError>{emailMessage}</FieldError>
          </Field>
          <Field data-invalid={passwordMessage ? true : undefined}>
            <FieldLabel htmlFor={`${id}-password`}>Password</FieldLabel>
            <Input
              id={`${id}-password`}
              name="password"
              type="password"
              autoComplete="new-password"
              value={password}
              disabled={pending}
              aria-invalid={passwordMessage ? true : undefined}
              onChange={(event) => {
                setPassword(event.target.value);
                setPasswordMessage(null);
              }}
            />
            <FieldError>{passwordMessage}</FieldError>
          </Field>
        </FieldGroup>
        <Button type="submit" className="w-full" loading={pending} disabled={pending}>
          Create account
        </Button>
      </form>
    </AuthPanel>
  );
}

import { RegisterPage } from '@/components/auth/register-page';

// onSubmit receives { name, email, password } once the fields are valid.
// loginHref defaults to /login.

export default function Page() {
  return <RegisterPage />;
}
